const expand = 'Category($select=CategoryName),Supplier($select=CompanyName,Country)';
const url = 'https://services.odata.org/V4/Northwind/Northwind.svc/Products?$format=json&$select=ProductID,ProductName,QuantityPerUnit,UnitPrice,UnitsInStock,UnitsOnOrder,ReorderLevel,Discontinued&$expand=' + encodeURIComponent(expand);
return [{ json: { url } }];

const paginas = $input.all();
const produtos = paginas.flatMap(p => p.json.value || []).map(p => ({
  id: p.ProductID,
  nome: p.ProductName,
  embalagem: p.QuantityPerUnit,
  categoria: p.Category ? p.Category.CategoryName : 'Sem categoria',
  fornecedor: p.Supplier ? p.Supplier.CompanyName : 'Sem fornecedor',
  pais_fornecedor: p.Supplier ? p.Supplier.Country : null,
  preco: p.UnitPrice,
  estoque: p.UnitsInStock,
  a_caminho: p.UnitsOnOrder,
  minimo: p.ReorderLevel,
  ativo: !p.Discontinued
}));
return [{ json: { paginas: paginas.length, produtos } }];

const d = $('Normaliza produtos').first().json;
const limpa = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const palavras = limpa(query.termo).split(/\s+/).filter(p => p.length > 1);
if (!palavras.length) return JSON.stringify({ status: 'PARAMETRO_INVALIDO', campo: 'termo' });
const notas = d.produtos.map(p => {
  const texto = limpa(p.nome + ' ' + p.categoria + ' ' + p.fornecedor).split(/[^a-z0-9]+/);
  return { p, nota: palavras.filter(w => texto.some(t => t.startsWith(w))).length };
}).filter(x => x.nota > 0);
if (!notas.length) return JSON.stringify({ status: 'NAO_ENCONTRADO', termo: query.termo });
const melhor = Math.max(...notas.map(x => x.nota));
const achados = notas.filter(x => x.nota === melhor).slice(0, 10).map(x => x.p);
return JSON.stringify({ status: 'OK', encontrados: achados.length, produtos: achados });

const d = $('Normaliza produtos').first().json;
const cat = String(query.categoria || '').toLowerCase();
const itens = d.produtos.filter(p => p.ativo && p.estoque <= p.minimo && (!cat || p.categoria.toLowerCase() === cat)).map(p => ({ nome: p.nome, categoria: p.categoria, estoque: p.estoque, minimo: p.minimo, a_caminho: p.a_caminho, falta_para_minimo: Math.max(p.minimo - p.estoque, 0), descoberto: p.estoque + p.a_caminho < p.minimo }));
if (!itens.length) return JSON.stringify({ status: 'SEM_DADOS' });
const limite = Number(query.limite) || itens.length;
const lista = itens.sort((a, b) => b.falta_para_minimo - a.falta_para_minimo || a.nome.localeCompare(b.nome)).slice(0, limite);
return JSON.stringify({ status: 'OK', abaixo_do_minimo: itens.length, zerados: itens.filter(i => i.estoque === 0).length, descobertos: itens.filter(i => i.descoberto).length, listados: lista.length, itens: lista });

const d = $('Normaliza produtos').first().json;
const cat = String(query.categoria || '').toLowerCase();
const base = d.produtos.filter(p => !cat || p.categoria.toLowerCase() === cat);
if (!base.length) return JSON.stringify({ status: 'SEM_DADOS' });
const r2 = v => Math.round(v * 100) / 100;
const valorDe = lista => lista.reduce((s, p) => s + p.preco * p.estoque, 0);
const ativos = base.filter(p => p.ativo);
const descontinuados = base.filter(p => !p.ativo);
const grupos = {};
for (const p of ativos) (grupos[p.categoria] = grupos[p.categoria] || []).push(p);
const categorias = Object.entries(grupos).map(([nome, lista]) => ({ categoria: nome, produtos: lista.length, unidades: lista.reduce((s, p) => s + p.estoque, 0), valor: r2(valorDe(lista)) })).sort((a, b) => b.valor - a.valor);
return JSON.stringify({ status: 'OK', valor_total: r2(valorDe(base)), valor_ativos: r2(valorDe(ativos)), unidades_ativos: ativos.reduce((s, p) => s + p.estoque, 0), produtos_ativos: ativos.length, valor_descontinuados: r2(valorDe(descontinuados)), unidades_descontinuados: descontinuados.reduce((s, p) => s + p.estoque, 0), produtos_descontinuados: descontinuados.length, categorias });
